package com.abhishek.hotelbooking.controller; import com.abhishek.hotelbooking.dto.hotel.HotelRequest; import com.abhishek.hotelbooking.entity.Hotel; import com.abhishek.hotelbooking.service.impl.HotelService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/hotels") public class HotelController { private final HotelService service; public HotelController(HotelService service){this.service=service;} @GetMapping public List<Hotel> all(){return service.all();} @GetMapping("/{id}") public Hotel get(@PathVariable Long id){return service.get(id);} @PreAuthorize("hasRole('ADMIN')") @PostMapping public Hotel create(@Valid @RequestBody HotelRequest r){return service.create(r);} @PreAuthorize("hasRole('ADMIN')") @DeleteMapping("/{id}") public void delete(@PathVariable Long id){service.delete(id);} }